package medium;public class SwapNodesInPairs{static class ListNode{int val;ListNode next;ListNode(int val){this.val=val;}}public static ListNode swapPairs(ListNode head){if(head==null||head.next==null)return head;ListNode next=head.next;head.next=swapPairs(next.next);next.next=head;return next;}public static void main(String[]args){System.out.println("Swap works\n");}}
